begin;

update public.legal_organisations
set overview = '5 Essex Chambers is a London public and civil law set specialising in areas including inquests and inquiries, police law, public and administrative law, information law, employment, human rights and regulatory work. Its student routes include annual funded pupillage, widening-access mini-pupillages and work experience, the 10,000 Interns programme, Inside Five applicant evenings and student-facing pupillage fairs.',
    research_checked_on = date '2026-10-15', next_review_on = date '2026-10-22', updated_at = now()
where id = '809887b0-9bf0-494a-8740-0afbe8503eb0';

update public.chambers
set pupillage_overview = '5 Essex Chambers recruits up to two 12-month pupils each year through the Pupillage Gateway. Pupils rotate through three supervisors and undertake their own work during the practising six. The current minimum package is £80,000: a £50,000 award and £30,000 guaranteed earnings, with up to £10,000 available as drawdown. The linked September 2027 vacancy closed on 22 January 2026; Vacatory will add the next competition when chambers releases its vacancy.',
    mini_pupillage_overview = '5 Essex does not accept general direct mini-pupillage applications. Placements are offered through Inner Temple PASS, Middle Temple’s Access to the Bar Award, Gray’s Inn’s Griffin Access Programme, the 10,000 Interns Foundation and the Bar Council Bar Placement Scheme. Applicants apply through the relevant partner when a dated cycle is open.',
    tenancy_overview = 'Vacatory excludes lateral recruitment, third-six and probationary-tenancy vacancies. Tenancy is recorded only as progression from the standard pupillage route; 5 Essex states that it recruits pupils who have the potential to become tenants.',
    research_checked_on = date '2026-10-15', next_review_on = date '2026-10-22', updated_at = now()
where organisation_id = '809887b0-9bf0-494a-8740-0afbe8503eb0';

